const operationSpecial=Object.freeze({"17":{"FREEZE":"Stage 17 operation FREEZE only: freeze the corrected candidate through application-controlled identities and exact component bytes after the approved change set; do not execute, verify, compare, root-cause, regress, or correct in this response.","EXECUTE_RUN":"Stage 17 operation EXECUTE_RUN only: execute the single application-reserved fresh run of the corrected frozen candidate; withhold prior outputs/reviewer feedback; do not verify, compare, RCA, regress, or correct in this response.","VERIFY":"Stage 17 operation VERIFY only: independently verify only the application-listed missing current matrix cells for the corrected iteration with sufficient evidence; do not execute a production run, compare, RCA, regress, or correct in this response.","COMPARE":"Stage 17 operation COMPARE only: compare all ten current corrected-run verification results requirement-by-requirement and identify correctness-affecting variance; do not execute, verify new cells, RCA, regress, or correct in this response.","ROOT_CAUSE":"Stage 17 operation ROOT_CAUSE only: root-cause every material current corrected-iteration defect to the earliest defective layer using evidence; do not execute, verify, compare again, create regressions, or correct in this response.","REGRESSION":"Stage 17 operation REGRESSION only: define and actually execute required regression proof for confirmed defects; do not execute production runs, compare, RCA again, or correct in this response.","CORRECT":"Stage 17 operation CORRECT only: correct evidenced root causes under change control, preserving versions and invalidation; do not execute the next iteration in this response."},"19":{"CONFIRM_FREEZE":"Stage 19 operation CONFIRM_FREEZE only: confirm the candidate is semantically and byte-identically unchanged from the converged candidate using application-owned identities/hashes; do not run executions in this response.","EXECUTE_RUN":"Stage 19 operation EXECUTE_RUN only: execute one reserved fresh confirmation run using the unchanged frozen package and no prior-run context; do not verify or compare in this response.","VERIFY":"Stage 19 operation VERIFY only: independently execute the complete applicable verification cells for the confirmation iteration; do not compare or conclude confirmation in this response.","COMPARE":"Stage 19 operation COMPARE only: compare all ten confirmation-run verification results and expose any variance or defects; do not perform regression verification or final confirmation in this response.","REGRESSION_VERIFY":"Stage 19 operation REGRESSION_VERIFY only: execute every still-applicable regression against the unchanged confirmation candidate and preserve sufficient evidence; do not perform final confirmation in this response.","CONFIRM":"Stage 19 operation CONFIRM only: evaluate supplied confirmation observations for new requirements, missed failures, defects, contradictions, or unexplained variance; the application owns the final confirmation determination."}});
