function selectedContextRecords(state,collection,scope={}){const list=safe(state?.projectData?.[collection]).filter(record=>record?.active!==false&&!record?.invalidatedBy),keys=['inputVersion','sourceSetVersion','requirementsVersion','testSuiteVersion','instructionVersion','iterationId','candidateId','runId','contextId','baselineId','productId'],policy=schema.RECORD_SCHEMAS?.[collection]?.commitPolicy,scoped=['REPLACE_CURRENT_STAGE_SET','APPEND_SCOPED','UPDATE_RESERVED','APPLICATION_DERIVED'].includes(policy);return list.filter(record=>{const rs=record?.scope||{};if(scoped&&!Object.keys(rs).length)return false;for(const key of keys){const expected=scope?.[key];if(expected===undefined||expected===null||expected==='')continue;const actual=rs?.[key];if(actual!==undefined&&actual!==null&&actual!==''&&String(actual)!==String(expected))return false;}if(collection==='runs'&&scope.runId&&recordId(record,'runs')!==String(scope.runId))return false;if(collection==='freshContexts'&&scope.contextId&&recordId(record,'freshContexts')!==String(scope.contextId))return false;return true;});}
